  select 'Pito', c.id, 'Traditional sorghum or millet beer brewed in northern Ghana, Burkina Faso and Nigeria.', 'burukutu', 'liter', true from c
  on conflict (name) do update set category_id = excluded.category_id, description = excluded.description,
    aliases = excluded.aliases returning id, unit)
insert into public.product_prices (product_id, price) select id, 10.0 from p where unit = 'liter'
  on conflict (product_id) do update set price = excluded.price;
